import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import {
  Search,
  Leaf,
  Tag,
  ArrowRight,
  ChevronLeft,
  ChevronRight
} from "lucide-react";

import {
  getAllSchemes,
  getByCategory,
  getByState
} from "../services/schemeService";

const SchemePage = () => {

  const [schemes, setSchemes] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  const [category, setCategory] = useState("");
  const [state, setState] = useState("");
  const [search, setSearch] = useState("");

  const [currentPage, setCurrentPage] = useState(1);
  const schemesPerPage = 8;

  useEffect(() => {
    fetchSchemes();
  }, []);

  const fetchSchemes = async () => {
    try {
      setLoading(true);
      const data = await getAllSchemes();
      setSchemes(data);
      setError("");
    } catch (err) {
      setError("Failed to load schemes");
    } finally {
      setLoading(false);
    }
  };

  const handleCategoryChange = async (e) => {
    const value = e.target.value;
    setCategory(value);
    setState("");
    setCurrentPage(1);

    try {
      if (!value) return fetchSchemes();
      const data = await getByCategory(value);
      setSchemes(data);
    } catch {
      setError("Error filtering category");
    }
  };

  const handleStateChange = async (e) => {
    const value = e.target.value;
    setState(value);
    setCategory("");
    setCurrentPage(1);

    try {
      if (!value) return fetchSchemes();
      const data = await getByState(value);
      setSchemes(data);
    } catch {
      setError("Error filtering state");
    }
  };

  const filteredSchemes = schemes.filter((scheme) =>
    scheme.schemeName.toLowerCase().includes(search.toLowerCase())
  );

  const totalPages = Math.ceil(filteredSchemes.length / schemesPerPage);
  const indexOfLast = currentPage * schemesPerPage;
  const indexOfFirst = indexOfLast - schemesPerPage;
  const currentSchemes = filteredSchemes.slice(indexOfFirst, indexOfLast);

  const changePage = (pageNumber) => {
    setCurrentPage(pageNumber);
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  // 🔥 LOADING UI
  if (loading) {
    return (
      <div style={{ textAlign: "center", marginTop: "100px" }}>
        <h2>🌿 Loading Schemes...</h2>
      </div>
    );
  }

  // ❌ ERROR UI
  if (error) {
    return (
      <div style={{ textAlign: "center", marginTop: "100px" }}>
        <h2>{error}</h2>
        <button onClick={fetchSchemes}>Retry</button>
      </div>
    );
  }

  return (
    <div className="container">

      <h2 className="main-heading">
        <Leaf size={30} />
        Government Schemes
      </h2>

      {/* 🔍 SEARCH + FILTER */}
      <div className="filters">

        <div className="search-box">
          <Search size={18} />
          <input
            type="text"
            placeholder="Search schemes..."
            value={search}
            onChange={(e) => {
              setSearch(e.target.value);
              setCurrentPage(1);
            }}
          />
        </div>

        <select value={category} onChange={handleCategoryChange}>
          <option value="">All Categories</option>
          <option value="Central Government">Central</option>
          <option value="Insurance">Insurance</option>
          <option value="Loan">Loan</option>
          <option value="Subsidy">Subsidy</option>
        </select>

        <select value={state} onChange={handleStateChange}>
          <option value="">All States</option>
          <option value="All India">All India</option>
          <option value="Maharashtra">Maharashtra</option>
          <option value="Punjab">Punjab</option>
        </select>

      </div>

      {/* ❗ EMPTY STATE */}
      {filteredSchemes.length === 0 && (
        <h3 style={{ textAlign: "center" }}>
          No schemes found 😢
        </h3>
      )}

      {/* 🟩 GRID */}
      <div className="grid">
        {currentSchemes.map((scheme) => (
          <div key={scheme.id} className="card">

            <img
              src={process.env.PUBLIC_URL + scheme.image}
              alt={scheme.schemeName}
              onError={(e) => {
                e.target.src = "/images/schemes/default.jpg";
              }}
            />

            <div className="card-body">
              <h3>{scheme.schemeName}</h3>

              <p className="category-text">
                <Tag size={16} />
                {scheme.category}
              </p>

              <p>
                {scheme.description?.substring(0, 100)}...
              </p>

              <Link to={`/scheme/${scheme.id}`} className="btn">
                View Details
                <ArrowRight size={16} />
              </Link>
            </div>

          </div>
        ))}
      </div>

      {/* 📄 PAGINATION */}
      {totalPages > 1 && (
        <div className="pagination">

          <button
            className="page-btn"
            disabled={currentPage === 1}
            onClick={() => changePage(currentPage - 1)}
          >
            <ChevronLeft size={18} /> Prev
          </button>

          <span className="page-info">
            Page {currentPage} of {totalPages}
          </span>

          <button
            className="page-btn"
            disabled={currentPage === totalPages}
            onClick={() => changePage(currentPage + 1)}
          >
            Next <ChevronRight size={18} />
          </button>

        </div>
      )}

    </div>
  );
};

export default SchemePage;
